 async function commitCalendar(next:ScheduleBlock[]){const before=new Map(calendarBlocks.map(block=>[block.scheduleBlockId,block])),after=new Map(next.map(block=>[block.scheduleBlockId,block])),changed=[...new Set([...before.keys(),...after.keys()])].filter(id=>JSON.stringify(before.get(id))!==JSON.stringify(after.get(id)));if(changed.length!==1){setNotice(t('Review one schedule change at a time.','هر بار یک تغییر زمان‌بندی را بررسی کنید.'));return}const blockId=changed[0],oldBlock=before.get(blockId),newBlock=after.get(blockId),issueId=(newBlock??oldBlock)?.issueId;if(!issueId)return;try{const preview=await core.previewSchedule(state.projectId,issueId,blockId,newBlock??null,oldBlock?.version??null);const result=await core.applySchedule(preview,crypto.randomUUID(),(bootstrap??await core.bootstrap()).session.csrfToken);setCalendarUndo({blocks:calendarBlocks,issues});const scoped=new Set(projectIssues.map(issue=>issue.id));setCalendarBlocks([...calendarBlocks.filter(block=>!scoped.has(block.issueId)),...result.blocks]);setNotice(t(`Demo schedule receipt ${result.receipt.id}. Deadline unchanged; Undo available.`,`رسید زمان‌بندی نمونه ${result.receipt.id}. موعد تغییر نکرد؛ واگردانی در دسترس است.`))}catch(error){setNotice(error instanceof Error?error.message:t('Schedule change failed. Draft remains unchanged.','تغییر زمان‌بندی ناموفق بود؛ پیش‌نویس تغییر نکرد.'))}}
