 function createCalendar(title:string,existingId:string|null,date:string,start:string,endDate:string,end:string){const minutes=Math.round((Date.parse(toInstant(endDate,end,state.calendarTimezone))-Date.parse(toInstant(date,start,state.calendarTimezone)))/60000);if(minutes<=0)return;let id=existingId;let nextIssues=issues;if(!id){const number=Math.max(0,...projectIssues.map(i=>Number(i.semanticKey.split('-')[1])||0))+1;id=crypto.randomUUID();const item:Issue={...seed()[0],id,projectId:state.projectId,semanticKey:`${activeProject?.key||'EMP'}-${number}`,title,titleEn:title,description:'',descriptionEn:'',acceptanceCriteria:[],acceptanceCriteriaEn:[],assigneeId:'',status:'todo',version:1,priority:'normal',blocked:false,blockerReason:null,blockerReasonEn:null,startDate:null,dueDate:null,dependencies:[],comments:[]};nextIssues=[...issues,item]}setIssues(nextIssues);core.replaceIssues(nextIssues);repository.save(nextIssues);void commitCalendar([...calendarBlocks,scheduleTimed(id,date,start,minutes,'engineering',crypto.randomUUID(),state.calendarTimezone)])}
