 async function transitionStatus(id:string,target:Status,source:WriteSource='manual',known?:WorkItem,after?:(items:Issue[])=>Issue[],fields:Record<string,unknown>={}){
  if(transitionLock.current.has(id))return false;transitionLock.current.add(id);
  const projectId=issues.find(issue=>issue.id===id)?.projectId??state.projectId;
  const key=crypto.randomUUID();setConflictDraft(null);setLastReceipt(null);setTransitionPending(t('Validating Demo transition…','اعتبارسنجی انتقال نمونه…'));
  try{
   const item=known??(selectedSnapshot?.id===id?selectedSnapshot:await core.getWorkItem(projectId,id));
   const session=(bootstrap??await core.bootstrap()).session;
   const result=await core.transition({orgId:session.orgId,projectId,issueId:id,transitionId:`to:${target}`,fields,ifMatch:item.etag,idempotencyKey:key,csrfToken:session.csrfToken,source,simulate:transitionScenario==='normal'?undefined:transitionScenario});
   setTransitionScenario('normal');let receipt:Receipt|null=result.kind==='applied'?result.receipt:null;
   if(result.kind==='accepted'){
    setTransitionPending(t('Operation queued · waiting for a receipt…','عملیات در صف است؛ در انتظار رسید…'));
    for(let attempt=0;attempt<12&&!receipt;attempt++){await new Promise(resolve=>setTimeout(resolve,120));const operation=await core.operation(projectId,result.operation.id);if(operation.state==='failed')throw new Error(t('The Demo operation failed. No status was changed.','عملیات نمونه ناموفق بود؛ وضعیت تغییر نکرد.'));if(operation.state==='succeeded')receipt=operation.receipt??null}
    if(!receipt)throw new Error(t('Operation still pending. Check it before another write.','عملیات هنوز معلق است؛ پیش از نوشتن دوباره آن را بررسی کنید.'));
   }
   if(!receipt)throw new Error(t('No receipt was returned.','رسیدی دریافت نشد.'));
   let next=core.snapshot();if(after)next=after(next);persist(next);setTransitionFieldDraft(null);const latestItem=await core.getWorkItem(projectId,id);
   if(activeProjectIdRef.current===projectId){setSelectedSnapshot(latestItem);setLastReceipt(receipt);setActivity(await core.listActivity(projectId,id));setEventState('');setTransitionPending('');setNotice(t('Transition applied in Demo with a receipt.','انتقال نمونه با رسید اعمال شد.'))}
   return true;
  }catch(error){
   if(error instanceof OutcomeUnknown){setTransitionScenario('normal');const receipt=await core.commandByKey(projectId,error.key);if(receipt){persist(core.snapshot());if(activeProjectIdRef.current===projectId){setSelectedSnapshot(await core.getWorkItem(projectId,id));setLastReceipt(receipt);setActivity(await core.listActivity(projectId,id));setEventState('');setTransitionPending('');setNotice(t('Lost response reconciled by the same intent key; one Demo receipt found.','پاسخ گم‌شده با همان کلید قصد بازیابی شد؛ یک رسید نمونه یافت شد.'))}return true}setTransitionPending(t('Outcome unknown. Reconcile before another write.','نتیجه نامعلوم است؛ پیش از نوشتن دوباره بررسی کنید.'));return false}
   if(error instanceof CoreProblem&&error.problem.status===412){const latest=await core.getWorkItem(projectId,id);if(activeProjectIdRef.current===projectId){const original=known??selectedSnapshot??latest;setConflictDraft({issueId:id,desired:target,latest,original,fields});setTransitionPending('');setNotice(t('Version conflict. Your requested status is kept for review.','تعارض نسخه؛ وضعیت درخواستی برای بررسی حفظ شد.'))}return false}
   if(error instanceof CoreProblem&&error.problem.code==='REQUIRED_FIELDS'){setTransitionFieldDraft({issueId:id,target,source,resolutionNote:String(fields.resolutionNote??''),error:error.problem.fieldErrors?.[0]?.message??error.problem.detail});setTransitionPending('');return false}
   const message=error instanceof CoreProblem?error.problem.detail:error instanceof Error?error.message:t('Transition failed.','انتقال ناموفق بود.');if(activeProjectIdRef.current===projectId){setTransitionPending('');setNotice(message);boardFeedback(message)}return false;
  }finally{transitionLock.current.delete(id)}
 }
 async function refreshScopedSnapshot(){try{const result=await core.listWorkItems(state.projectId);setReadCount(result.meta.count.value);if(selected){setSelectedSnapshot(await core.getWorkItem(state.projectId,selected.id));setActivity(await core.listActivity(state.projectId,selected.id))}setEventState('')}catch{setEventState(t('Scoped Demo refresh failed. Retry.','بازخوانی محدودهٔ نمونه ناموفق بود؛ دوباره تلاش کنید.'))}}
