 function edit(id:string,patch:Partial<Issue>) {const current=issues.find(i=>i.id===id);if(!current)return;if(patch.status&&patch.status!==current.status){void transitionStatus(id,patch.status);return}void (async()=>{try{const item=await core.getWorkItem(current.projectId,id);if(item.version!==current.version){setNotice(t('This issue changed. Open it to review the latest version.','این کار تغییر کرده است؛ برای بررسی نسخهٔ جدید آن را باز کنید.'));open(current);return}const session=(bootstrap??await core.bootstrap()).session;const draft=draftFromIssue(current);if(patch.assigneeId!==undefined)draft.assigneeId=patch.assigneeId;if(patch.priority!==undefined)draft.priorityId=patch.priority;const result=await core.writeWorkItem({orgId:session.orgId,projectId:current.projectId,issueId:id,draft,ifMatch:item.etag,schemaRevision:(workSchema??await core.getWorkItemSchema(current.projectId)).revision,idempotencyKey:crypto.randomUUID(),csrfToken:session.csrfToken,source:'manual'});handleWorkItemResult(result)}catch(error){setNotice(error instanceof Error?error.message:t('Quick edit failed.','ویرایش سریع ناموفق بود.'))}})(); }
