 async function moveBoard(move:BoardMove,fields:Record<string,unknown>={}){
  if(boardLock.current.has(move.id))return;const original=projectIssues.find(issue=>issue.id===move.id);if(!original){boardFeedback(t('The card could not be found.','کارت پیدا نشد.'));return}
  const snapshot=await core.getBoardSnapshot(state.projectId);if(!targetStatus(snapshot.workflow,move.column)){boardFeedback(t('This column has no mapped drop status. The card stayed in place.','این ستون وضعیت مقصد ندارد؛ کارت جابه‌جا نشد.'));return}
  const visible=cardsInColumn(rows,move.area,move.column,snapshot.workflow).filter(issue=>issue.id!==move.id),at=Math.max(0,Math.min(move.index,visible.length));const sourceColumn=columnForStatus(snapshot.workflow,original.status);if(original.area===move.area&&sourceColumn===move.column){const sourceCards=cardsInColumn(rows,original.area,move.column,snapshot.workflow);if(sourceCards.findIndex(issue=>issue.id===original.id)===at)return}
  boardLock.current.add(move.id);setBoardPending(move.id);
  try{const current=await core.getWorkItem(state.projectId,move.id);if(current.version!==original.version)throw new CoreProblem({type:'urn:empireproject:problem:version-conflict',title:'Version conflict',status:412,code:'VERSION_CONFLICT',detail:'The card changed while this move was being prepared.'});const fresh=await core.getBoardSnapshot(state.projectId),session=(bootstrap??await core.bootstrap()).session;const result=await core.placeBoardCard({orgId:session.orgId,projectId:state.projectId,issueId:move.id,targetColumnId:move.column,targetArea:move.area,beforeId:visible[at-1]?.id??null,afterId:visible[at]?.id??null,ifMatch:current.etag,rankRevision:fresh.rankRevision,fields,idempotencyKey:crypto.randomUUID(),csrfToken:session.csrfToken,source:'board'});handleWorkItemResult(result);setBoardSnapshot(await core.getBoardSnapshot(state.projectId));setBoardDraft(null);boardFeedback(t(`Demo receipt ${result.receipt.id} confirms the board move.`,`رسید آزمایشی ${result.receipt.id} جابه‌جایی برد را تأیید می‌کند.`))}
  catch(error){if(error instanceof CoreProblem&&error.problem.code==='REQUIRED_FIELDS'){setBoardDraft({move,resolutionNote:String(fields.resolutionNote??''),requiresResolution:true,error:error.problem.fieldErrors?.[0]?.message??error.problem.detail});boardFeedback(t('A required transition field is missing. The card stayed in place.','فیلد لازم انتقال وارد نشده است؛ کارت در جای خود ماند.'))}else if(error instanceof CoreProblem&&(error.problem.status===412||error.problem.code==='RANK_CONFLICT')){const latest=core.snapshot();setIssues(latest);repository.save(latest);setBoardSnapshot(await core.getBoardSnapshot(state.projectId));setBoardDraft({move,resolutionNote:String(fields.resolutionNote??''),requiresResolution:Object.hasOwn(fields,'resolutionNote'),error:t('The card or rank changed. Your move is preserved; review and retry.','کارت یا رتبه تغییر کرد؛ جابه‌جایی شما حفظ شد. بررسی و دوباره تلاش کنید.')});boardFeedback(t('Version or rank conflict. Source position was preserved.','تعارض نسخه یا رتبه؛ جای اصلی کارت حفظ شد.'))}else{const message=error instanceof CoreProblem?error.problem.detail:error instanceof Error?error.message:t('Board move failed.','جابه‌جایی برد ناموفق بود.');boardFeedback(message)}}finally{boardLock.current.delete(move.id);setBoardPending(null)}
 }

