 async function run(value=command) {
  if(!value.trim()) return;
  setCommand('');
  setClarification(null);
  const aiContext=currentAIContext();
  await latest.current.run(()=>aiClient.current.submit(value,aiContext,issues),output=>{
   setAIOutput(safeAIOutput(output));setAIPrompt(value);setAIError('');
   if(output.kind==='clarifying_question'){setAssistant(true);setAIQuestionOpen(true);setAIDraftText('');setAIOtherOpen(false);setNotice(t('Demo clarification needs your answer; no action was sent.','پرسش نمونه به پاسخ شما نیاز دارد؛ اقدامی ارسال نشده است.'));return}
   if(output.kind==='insight_case'){setAssistant(true);setNotice(t('Demo insight separates observation from hypothesis.','بینش نمونه مشاهده را از فرضیه جدا می‌کند.'));return}
   if(output.kind!=='answer'){setAssistant(true);setNotice(t('The response could not change the workspace.','پاسخ نتوانست فضای کار را تغییر دهد.'));return}
   const intent=output.intent??{type:'unsupported' as const};
   let reply:string;
   if(intent.type==='openIssue'&&!projectIssues.some(i=>i.id===intent.id)&&!(state.projectId==='payment'&&flowGraph.nodes.some(i=>i.id===intent.id))) reply=t('That issue is not in this demo.','این شناسه در نمونه وجود ندارد.');
   else if(intent.type==='switchProjectQuery'){const found=matchProjects(projects,intent.query);if(found.length===1){switchProject(found[0].id,intent.remaining);reply=t(`Switched to ${found[0].name}.`,`پروژه ${found[0].nameFa} باز شد.`)}else if(found.length>1){setProjectChoices(found.map(p=>p.id));reply=t('Choose a project key in the browser.','کلید پروژه را در مرورگر انتخاب کنید.')}else reply=t('No accessible project matches that name.','پروژهٔ در دسترسی با این نام پیدا نشد.')}
   else if(intent.type==='backProject'){const id=projectHistory.current.pop();if(id&&switchProject(id,false,true))reply=t('Previous project restored.','پروژهٔ قبلی بازیابی شد.');else reply=t('No previous accessible project.','پروژهٔ قبلی در دسترس نیست.')}
   else if(intent.type==='helpUnblock'&&!intent.id) reply=t('Select an issue first. Open an issue or choose “Draft next step” in the investigation.','ابتدا یک کار انتخاب کنید؛ جزئیات را باز کنید یا «پیش‌نویس گام بعد» را انتخاب کنید.');
   else if(intent.type==='unsupported') reply=t('This demo does not support that prompt. Try “Show remaining work”, “Why is delivery at risk?” or “Help me unblock this”. No data was changed.','این فرمان پشتیبانی نمی‌شود. «ایشوهای مانده این اسپرینت را نشان بده»، «چرا تحویل در خطر است؟» یا «کمک کن این مانع را رفع کنم» را امتحان کنید. داده تغییر نکرد.');
   else if(intent.type==='explain') reply=context?`${context.semanticKey}: ${description(context,locale)}`:t('Views share one query. The workspace has not changed.','نماها از یک پرس‌وجوی مشترک استفاده می‌کنند. صفحه تغییر نکرد.');
   else {if(['showWorkflow','whyWorkflow','workflowPath','workflowBlockers'].includes(intent.type)&&state.projectId!=='payment')switchProject('payment');setNav(n=>navigate(n,intent));if(['showWorkflow','whyWorkflow','workflowPath','showCalendar','showMyCalendarWeek','calendarNextWeek'].includes(intent.type))setAssistant(false);if(intent.type==='showWorkflow')setFlowFitSignal(n=>n+1);reply=intent.type==='investigateRisk'?t('Investigation opened from recorded sprint data.','بررسی بر اساس داده ثبت‌شده اسپرینت باز شد.'):intent.type==='helpUnblock'?t('Opened a local follow-up workspace. Nothing has been sent.','فضای پیگیری محلی باز شد. چیزی ارسال نشده است.'):t('Workspace updated. Your context is preserved.','فضای کار به‌روز شد؛ زمینه حفظ شده است.');}
   setNotice(reply);setMessages(m=>[...m,{prompt:value,reply}]);
  });
 }
 function reset() {latest.current.invalidate();setClarification(null);persist([...seed(),...projectSeedIssues()]);setCalendarBlocks(calendarSeed());core.replaceScheduleBlocks(calendarSeed());core.resetSprintPlans();for(const project of projects)core.phase12.resetDemo(project.id);setCalendarUndo(null);setFlowGraph(structuredClone(paymentFlow));setFlowFitSignal(n=>n+1);setNav({current:initialState,history:[]});projectSnapshots.current={};projectHistory.current=[];setScenario('normal');setWipLimitState(core.phase13.snapshot(initialState.projectId).config.board.wip[0]?.limit??4);setBoardNotice('');setBoardDraft(null);setBoardPending(null);setBoardEpoch(n=>n+1);try{localStorage.removeItem('empire-kanban-wip-v1');for(const key of Object.keys(localStorage).filter(key=>key.startsWith('empire-kanban-wip-v1:')))localStorage.removeItem(key);localStorage.removeItem('empire-kanban-collapsed-v1');localStorage.removeItem('empire-demo-last-view');localStorage.removeItem('empire-active-project-v1:local-demo:workspace');for(const key of Object.keys(localStorage).filter(key=>key.startsWith('empire-datacart-')))localStorage.removeItem(key)}catch{/* session reset still succeeds */}}
 function editFlow(id:string,status:'done'|'needs_decision'|'in_progress'){const current=issues.find(issue=>issue.id===id);if(!current)return;const target=status==='done'?'completed':status==='in_progress'?'in_progress':'todo';if(current.status!==target)void transitionStatus(id,target,'manual');}
