    <section className="workspace-heading"><div><div className="eyebrow"><span className="live-dot"/>{isOrgComposition(state.composition)?t('ORGANIZATION','سازمان','المؤسسة'):t('SPRINT 12','اسپرینت ۱۲')}<span>/</span>{isOrgComposition(state.composition)?t('Local Demo','نمونهٔ محلی','عرض محلي'):fa?activeProject?.nameFa:activeProject?.name}</div><h1>{isOrgComposition(state.composition)?compositionTitle:state.composition==='people'?t('People & access','افراد و دسترسی'):state.composition==='settings'?t('Versioned settings','تنظیمات نسخه‌دار'):state.composition==='overview'?t('Overview & Attention','نمای کلی و توجه'):state.composition==='reports'?t('Evidence-based reports','گزارش‌های مستند'):state.composition==='releases'?t('Releases','انتشارها'):state.composition==='gallery'?t('Gallery','گالری'):state.composition==='knowledge'?t('Knowledge','دانش'):state.composition==='agents'?t('Agents, Runs & Reviews','عامل‌ها، اجراها و بازبینی‌ها'):state.composition==='intake'?t('Intake & plan','ورودی و برنامه'):state.composition==='datacart'?t('DataCart import','ورود سبد داده'):state.composition==='planning'?t('Backlog & Sprints','بک‌لاگ و اسپرینت‌ها'):state.composition==='calendar'?t('Sprint calendar','تقویم اسپرینت'):state.composition==='workflow'?state.projectId==='payment'?t('Payment release Work Flow','جریان کار انتشار پرداخت'):fa?activeProject?.nameFa:activeProject?.name:fa?activeProject?.nameFa:activeProject?.name}</h1><p>{isOrgComposition(state.composition)?t('Authorized organization work across projects.','کار سازمانی مجاز میان پروژه‌ها.'):state.composition==='people'?t('Effective grants, memberships and lineage.','مجوزهای مؤثر، عضویت‌ها و منشأ آن‌ها.'):state.composition==='settings'?t('Draft, validate, approve and publish configuration.','پیکربندی را پیش‌نویس، اعتبارسنجی، تأیید و منتشر کنید.'):state.composition==='overview'?t('Recorded project signals and the work behind them.','نشانه‌های ثبت‌شدهٔ پروژه و کارهای پشت آن‌ها.'):state.composition==='reports'?t('Current snapshots with definitions and drill-downs.','تصویرهای فعلی با تعریف و جزئیات قابل‌ردیابی.'):state.composition==='releases'?t('Review gates and simulated delivery evidence.','بازبینی دروازه‌ها و شواهد تحویل شبیه‌سازی‌شده.'):state.composition==='gallery'?t('Trace simulated artifacts to their Run and independent review.','خروجی‌های شبیه‌سازی‌شده را تا Run و بازبینی مستقل دنبال کنید.'):state.composition==='knowledge'?t('Search versioned project sources and open authorized citations.','منابع نسخه‌دار پروژه را جست‌وجو و استنادهای مجاز را باز کنید.'):state.composition==='agents'?t('Inspect Demo readiness, run attempts and independent evidence reviews.','آمادگی نمونه، تلاش‌های اجرا و بازبینی مستقل شواهد را بررسی کنید.'):state.composition==='intake'?t('Clarify sources and review a versioned execution plan.','منابع را روشن کنید و برنامهٔ اجرای نسخه‌دار را بازبینی کنید.'):state.composition==='datacart'?t('Stage and review source rows before a validated import.','ردیف‌های منبع را پیش از ورود معتبر آماده و بازبینی کنید.'):state.composition==='planning'?t('Plan commitments without inventing capacity or Goal achievement.','تعهدها را بدون فرض ظرفیت یا دستیابی به هدف برنامه‌ریزی کنید.'):state.composition==='calendar'?t('Plan work without changing issue deadlines.','کارها را بدون تغییر موعد ایشو برنامه‌ریزی کنید.'):state.composition==='workflow'?t('Trace this project’s work and dependencies.','کارها و وابستگی‌های این پروژه را دنبال کنید.'):t('Project work, focused on the current sprint.','کارهای پروژه در اسپرینت فعلی.')}</p></div>{!isOrgComposition(state.composition)&&state.composition!=='workflow'&&state.composition!=='intake'&&state.composition!=='agents'&&state.composition!=='gallery'&&state.composition!=='knowledge'&&state.composition!=='overview'&&state.composition!=='reports'&&state.composition!=='releases'&&<button className="primary" onClick={()=>setCreating(true)}><Plus size={15}/>{t('New issue','ساخت Issue')}</button>}</section>
